import React, {useState} from 'react';
import '../css/login.css';

// Font Awesome
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faN, faComment } from '@fortawesome/free-solid-svg-icons';

import { useNavigate } from 'react-router';

function Login() {
  // 초기값
  const [formData, setFormData] = useState({
    user_id:'',
    user_pw:''
  });

  const nameChange = (e) => {
    const {name, value} = e.target;

    setFormData((prev)=>({
      ...prev,
      [name]:value
    }));
  }

  const loginCheck = () => {
  if(formData.user_id === 'test' && formData.user_pw === '1234'){
    alert('로그인 성공');
  }else{
    alert('로그인 실패');
  }
}



  const navigate = useNavigate();
  return (
    <>
    <div className="login">
        <h2>로그인</h2>
        <div className="input_row">
          <label htmlFor="user_id">아이디</label>
          <input type="text" id="user_id" name="user_id" value={formData.user_id} onChange={nameChange} placeholder="아이디를 입력해주세요" />
        </div>

        <div className="input_row">
          <label htmlFor="user_pw">비밀번호</label>
          <input type="password" id="user_pw" name="user_pw" value={formData.user_pw} onChange={nameChange} placeholder="비밀번호를 입력해주세요" />
        </div>

        
        <ul className="find">
          <li>아이디 찾기</li>
          <li>비밀번호 찾기</li>
        </ul>
        
        <div className="btn">
        <button type="button" className="login_btn"
        onClick={loginCheck}
        >
          로그인
        </button>
        <button
          type="button"
          className="move_to_join"
          onClick={() => navigate('/join')}
        >
          회원가입
        </button>
        </div>

        <h2>간편 로그인</h2>
        <div className="sns_login">
          <button type="button" className="naver">
            <FontAwesomeIcon icon={faN} />
            네이버로 계속하기
          </button>

          <button type="button" className="kakao">
            <FontAwesomeIcon icon={faComment} />
            카카오로 계속하기
          </button>
        </div>
    </div>
    </>
  )
}

export default Login