import React from 'react'
import '../css/Notfound.css';

function Notfound() {
  return (
    <>
    <article>
      <h2>Notfound!</h2>
      <img
        src={`${process.env.PUBLIC_URL}/images/error.png`}
        alt="경로 오류"
      />
      <p>페이지를 찾을 수 없습니다.</p>
    </article>
    </>
  )
}

export default Notfound