import React from 'react'

import {Swiper, SwiperSlide} from 'swiper/react';
import {Pagination, Navigation, Autoplay, Scrollbar} from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faHeart, faCartShopping, faUser, faMagnifyingGlass } from '@fortawesome/free-solid-svg-icons';

const products = [
  {
    id: 1,
    name: '[JMW] BLDC 미용실 드라이기 2종 (택1)',
    image: '/images/recommand1.jpg',
    coupon: 5,
    originalPrice: 149000,
    discount: 56,
    price: 65550,
    review: 46
  },
  {
    id: 2,
    name: '[인바디] 체지방 측정 다이얼 인바디 체중계 H30N 블루투스/와이파이',
    image: '/images/recommand2.jpg',
    coupon: 5,
    originalPrice: 379500,
    discount: 7,
    price: 351025
  },
  {
    id: 3,
    name: '[인바디] 체지방 측정 체중계 H40N 와이파이 3종 (택1)',
    image: '/images/recommand3.jpg',
    coupon: 5,
    originalPrice: 519000,
    discount: 5,
    price: 493050
  },
  {
    id: 4,
    name: '[위닉스] 제습기 12L DXAE120-NEK카밍베이지 내부건조 뽀송',
    image: '/images/recommand4.jpg',
    originalPrice: 299000,
    discount: 3,
    price: 289000
  }
];


function Kurly() {

  return (
    <>

    {/* =========메인 슬라이드========= */}
    <section className='slide'>
      <Swiper
        modules={[Navigation, Pagination, Scrollbar, Autoplay]}
        spaceBetween={0} //슬라이드 이미지 사이 간격
        slidesPerView={1} //한 페이지당 이미지 몇 장?
        navigation
        autoplay={{delay:3000}}
        pagination={{clickable:true}} //컨트롤버튼 클릭 가능 여부
        scrollbar={{draggable:true}} //터치스크롤 가능 여부
        className='mslide' //슬라이드 서식
      >
        <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide1.jpg`} alt="" /></SwiperSlide>
        <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide2.jpg`} alt="" /></SwiperSlide>
        <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide3.jpg`} alt="" /></SwiperSlide>
        <SwiperSlide><img src={`${process.env.PUBLIC_URL}/images/slide4.jpg`} alt="" /></SwiperSlide>
      </Swiper>
    </section>

    {/* 추천 상품 */}
    <section className='recommand'>
      <h3 className='title3'>MD의 추천</h3>

      <ul className='tab'>
        <li>헤어ㆍ바디ㆍ구강</li>
        <li>가구ㆍ인테리어</li>
        <li>건강식품</li>
        <li>가전제품</li>
        <li>패션의류</li>
        <li>스킨케어ㆍ메이크업</li>
        <li>간식ㆍ과자ㆍ떡</li>
        <li>전통주</li>
        <li>커피ㆍ차</li>
      </ul>

      {/* 상품 반복 출력 */}
      <ul className='md_products'>
        {products.map(function(product) {
          return (
            <li key={product.id}>

              {/* 상품 이미지 및 쿠폰 */}
              <div className='img_box'>
                <img
                  src={`${process.env.PUBLIC_URL}${product.image}`}
                  alt={product.name}
                />

                {product.coupon !== undefined && (
                  <span className='coupon'>
                    +{product.coupon}% 쿠폰
                  </span>
                )}
              </div>

              {/* 담기 버튼 */}
              <button type='button'>
                <FontAwesomeIcon icon={faCartShopping} /> 담기
              </button>

              {/* 상품명 */}
              <p className='product_name'>
                {product.name}
              </p>

              {/* 정상 가격 */}
              <del className='original_price'>
                {product.originalPrice.toLocaleString('ko-KR')}원
              </del>

              {/* 할인율 및 판매 가격 */}
              <div className='price_box'>
                <span className='discount'>
                  {product.discount}%
                </span>

                <strong className='price'>
                  {product.price.toLocaleString('ko-KR')}원
                </strong>
              </div>

              {/* 리뷰 */}
              {product.review !== undefined && (
                <span className='review'>
                  {product.review}
                </span>
              )}

            </li>
          );
        })}
      </ul>
    </section>
    {/* 배너 */}
    <div className='banner'>
      <img src ='/images/banner.jpg' alt='배너' />
    </div>
    {/* =========인기 상품========= */}
    <article>
      <h3 className='title3'>🏆실시간 인기 랭킹🏆</h3>
      <p>가장 인기있는 상품만 모아보세요!</p>
      <div className='product_list'>
        <ul>
          <li>
            <img src={`${process.env.PUBLIC_URL}/images/best1.jpg`} alt=''/>
            <div className='bottom'>
              <p className='number'>1</p>
              <div>
                <p className='name'>[비비고] 순살 생선구이 6종 (택1)</p>
                <ul>
                  <li className='percent'>9%</li>
                  <li className='price'>4,980원~</li>
                </ul>
              </div>
            </div>

          </li>
          <button>담기</button>
        </ul>
    {/* ================= */}
        <ul>
          <li><img src={`${process.env.PUBLIC_URL}/images/best2.jpg`} alt=''/>
          <div className='bottom'>
            <p className='number'>2</p>
            <div>
              <p className='name'>[Dole] 스위티오 바나나 2종 (택1)</p>
              <ul>
                <li className='percent'>5%</li>
                <li className='price'>3,990원~</li>
              </ul>
            </div>
          </div>
          </li>
          <button>담기</button>
        </ul>
    {/* ================= */}
        <ul>
          <li><img src={`${process.env.PUBLIC_URL}/images/best3.jpg`} alt=''/>
          <div className='bottom'>
            <p className='number'>3</p>
            <div>
              <p className='name'>[이연복의 목란] 짬뽕 2인분 (맵기 선택)</p>
              <ul>
                <li className='percent'>15%</li>
                <li className='price'>12,325원~</li>
              </ul>
            </div>
          </div>
          </li>
          <button>담기</button>
        </ul>
    {/* ================= */}
        <ul>
          <li><img src={`${process.env.PUBLIC_URL}/images/best4.jpg`} alt=''/>
          <div className='bottom'>
            <p className='number'>4</p>
            <div>
              <p className='name'>[KF365] 양념 소불고기 4종 (택1)</p>
              <ul>
                <li className='percent'>28%</li>
                <li className='price'>14,310원~</li>
              </ul>
            </div>
          </div>
          </li>
          <button>담기</button>
        </ul>
    {/* ================= */}
        <ul>
          <li><img src={`${process.env.PUBLIC_URL}/images/best5.jpg`} alt=''/>
          <div className='bottom'>
            <p className='number'>5</p>
            <div>
              <p className='name'>[KF365] 당도선별 제주감귤 2.5kg (로얄과)</p>
              <ul>
                <li className='percent'>44%</li>
                <li className='price'>13,900원~</li>
              </ul>
            </div>
          </div>
          </li>
          <button>담기</button>
        </ul>
    {/* ================= */}

      </div>
      <button className='all'>전체보기</button>
    </article>
    </>
  )
}

export default Kurly


