import React from 'react'
import '../css/join.css';

function Join()  {
  return (
    <>
    <main className="join">
      <div className="join_top">
        <h2>회원가입</h2>
        <p><span>*</span>필수입력사항</p>
      </div>
      <div className="input">
        <div className="input_row">
          <label htmlFor="user_id">아이디<span>*</span></label>
          <input type="text" id="user_id" placeholder="아이디를 입력해주세요" />
        </div>

        <div className="input_row">
          <label htmlFor="user_pw">비밀번호<span>*</span></label>
          <input type="password" id="user_pw" placeholder="비밀번호를 입력해주세요" />
        </div>
        
        <div className="input_row">
          <label htmlFor="user_pw_check">비밀번호확인<span>*</span></label>
          <input type="password" id="user_pw_check" placeholder="비밀번호를 한번 더 입력해주세요" />
        </div>
        
        <div className="input_row">
          <label htmlFor="user_name">이름<span>*</span></label>
          <input type="text" id="user_name" placeholder="이름을 입력해주세요" />
        </div>

        <div className="input_row">
          <label htmlFor="user_email">이메일<span>*</span></label>
          <div className="email_box">
            <input type="text" id="user_email" placeholder="예: marketkurly" />
            <span>@</span>
            <select name="email" id="email" defaultValue="">
              <option value="">선택하기</option>
              <option value="naver.com">naver.com</option>
              <option value="gmail.com">gmail.com</option>
              <option value="daum.net">daum.net</option>
            </select>
          </div>
        </div>

        <div className="input_row">
          <label htmlFor="phone">휴대폰<span>*</span></label>
          <input type="tel" id="phone" placeholder="숫자만 입력해주세요" />
          <button>인증번호 받기</button>
        </div>
        <div className="input_row">
          <label htmlFor="address">주소<span>*</span></label>
          <input type="button" id="address" value="주소 검색" />
        </div>
        <p>배송지에 따라 상품 정보가 달라질 수 있습니다.</p>

        <div className="input_row gender_row">
          <span id="gender_title">성별</span>

          <div className="gender_box" role="group" aria-labelledby="gender_title">
            <label>
              <input type="radio" name="gender" value="male" />
              남자
            </label>

            <label>
              <input type="radio" name="gender" value="female" />
              여자
            </label>

            <label>
              <input type="radio" name="gender" value="none" defaultChecked />
              선택안함
            </label>
          </div>
        </div>

        <div className="input_row">
          <label htmlFor="birth_year">생년월일</label>

          <div className="birth_box">
            <input
              type="text"
              id="birth_year"
              placeholder="YYYY"
              maxLength={4}
              inputMode="numeric"
              aria-label="출생 연도"
            />
            <span>/</span>
            <input
              type="text"
              placeholder="MM"
              maxLength={2}
              inputMode="numeric"
              aria-label="출생 월"
            />
            <span>/</span>
            <input
              type="text"
              placeholder="DD"
              maxLength={2}
              inputMode="numeric"
              aria-label="출생 일"
            />
          </div>
        </div>

        <div className="input_row other_row">
          <span className="input_title">추가입력 사항</span>

          <label>
            <input type="radio" name="other" id="friend" value="friend" />
            친구초대 추천인 아이디
          </label>
        </div>

      </div>

      <div className="join_bottom">
        {/* 이용약관 동의 */}
        <fieldset className="terms">
          <legend>이용약관동의<span>*</span></legend>

          {/* 전체 동의 */}
          <div className="agree_all">
            <label>
              <input type="checkbox" id="agree_all" />
              전체 동의합니다
            </label>

            <p>
              선택 항목에 동의하지 않은 경우도
              회원가입 및 일반적인 서비스를 이용할 수 있습니다.
            </p>
          </div>

          {/* 개별 이용약관 */}
          <ul className="agree_list">

            <li>
              <label>
                <input type="checkbox" name="terms" required />
                컬리 이용약관 동의 <span>(필수)</span>
              </label>
              <button type="button" aria-label="컬리 이용약관 상세보기">›</button>
            </li>

            <li>
              <label>
                <input type="checkbox" name="privacy" required />
                개인정보 수집·이용 <span>(필수)</span>
              </label>
              <button type="button" aria-label="개인정보 수집·이용 상세보기">›</button>
            </li>

            <li>
              <label>
                <input type="checkbox" name="event" />
                이벤트 및 혜택정보 발송을 위한 수집·이용
                <span>(선택)</span>
              </label>
              <button type="button" aria-label="이벤트 약관 상세보기">›</button>
            </li>

            <li>
              <label>
                <input type="checkbox" name="marketing" />
                광고성 정보 수신 <span>(선택)</span>
              </label>
            </li>

            {/* 광고성 정보 수신 방법 */}
            <li className="agree_sns">
              <label>
                <input type="checkbox" name="sms" />
                문자
              </label>

              <label>
                <input type="checkbox" name="email_marketing" />
                이메일
              </label>

              <label>
                <input type="checkbox" name="kakao" />
                카카오
              </label>
            </li>

            <li>
              <label>
                <input type="checkbox" name="age" required />
                본인은 만 14세 이상입니다. <span>(필수)</span>
              </label>
            </li>

          </ul>
        </fieldset>
        <button type="button" className="join_btn">
          가입하기
        </button>
        
      </div>
    </main>
    </>
  )
}

export default Join